Q: Add a range of values onto an existing range of values A: <p>Use <code>Array.reduce()</code> and <code>Array.map()</code>, like this:</p>
<pre class="lang-js prettyprint-override"><code>function UntitledMacro() {
  const ss = SpreadsheetApp.getActive();
  const possessionValues = ss.getRange('Possession Simulation!B11:L20').getValues();
  const boxScore = ss.getRange('Box Score!C2:M11');
  boxScore.setValues(addArrays(boxScore.getValues(), possessionValues));
}

function addArrays(...arrays) {
  return arrays.reduce((a, c) =&gt;
    a.map((row, i) =&gt; row.map((v, j) =&gt; (Number(v) || 0) + (Number(c[i][j]) || 0)))
  );
}
</code></pre>
<p>See
<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/reduce" rel="nofollow noreferrer">Array.reduce()</a>,
<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/map" rel="nofollow noreferrer">Array.map()</a> and
<a href="https://stackoverflow.com/tags/google-apps-script/info">Apps Script at Stack Overflow</a>.</p>
